import sys
from collections import deque

def main():
    n, d = map(int, sys.stdin.readline().split())
    coords = []
    for _ in range(n):
        x, y = map(int, sys.stdin.readline().split())
        coords.append((x, y))

    adj = [[] for _ in range(n)]
    d_squared = d * d

    for i in range(n):
        xi, yi = coords[i]
        for j in range(n):
            if i == j:
                continue
            dx = xi - coords[j][0]
            dy = yi - coords[j][1]
            dist_sq = dx * dx + dy * dy
            if dist_sq <= d_squared:
                adj[i].append(j)

    visited = [False] * n
    q = deque()
    q.append(0)
    visited[0] = True

    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)

    for res in visited:
        print("Yes" if res else "No")

if __name__ == "__main__":
    main()
