import bisect
import sys

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    A = list(map(int, input[ptr:ptr + N]))
    ptr += N
    A = [0] + A  # make A 1-based
    pre = [0] * (N + 1)
    for i in range(2, N + 1):
        if i % 2 == 0:
            pre[i] = pre[i-1]
        else:
            pre[i] = pre[i-1] + (A[i] - A[i-1])
    Q = int(input[ptr])
    ptr += 1
    for _ in range(Q):
        l = int(input[ptr])
        r = int(input[ptr + 1])
        ptr += 2

        def compute(t):
            k = bisect.bisect_right(A, t) - 1
            if k == 0:
                return 0
            if k % 2 == 0:
                return pre[k] + (t - A[k])
            else:
                return pre[k]

        ans = compute(r) - compute(l)
        print(ans)

if __name__ == "__main__":
    main()
