class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 2)  # 1-based indexing

    def update(self, idx, delta):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

def has_between(ft, a, b):
    if a >= b:
        return False
    upper = b - 1
    lower = a + 1
    if upper < lower:
        return False
    sum_upper = ft.query(upper)
    sum_lower = ft.query(lower - 1)
    return sum_upper - sum_lower > 0

