sorted_list = [1, 2, 3, 4, 5]
if A == sorted_list:
    print("No")
else:
    # Count the number of adjacent inversions
    count = 0
    for i in range(4):
        if A[i] > A[i+1]:
            count += 1
    # Check if exactly one inversion exists
    if count == 1:
        print("Yes")
    else:
        print("No")
